let state=load(); delete state.experience; state.challengeSubmissions=state.challengeSubmissions||{}; state.roadmapCompleted=state.roadmapCompleted||{}; state.selectedRoadmap=state.selectedRoadmap||''; state.challengeLength=Math.max(7,Math.min(1000,Number(state.challengeLength)||150));
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));return s?merge(seed,s):structuredClone(seed)}catch{return structuredClone(seed)}}
function merge(base,s){return {...structuredClone(base),...s,profile:{...base.profile,...(s.profile||{})},connections:{...base.connections,...(s.connections||{})}}}
function save(){delete state.experience;localStorage.setItem(KEY,JSON.stringify(state));renderAll()}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function closeMobileNav(){
  const sidebar=$('#sidebar'),backdrop=$('#sidebarBackdrop'),button=$('#mobileMenu');
  sidebar?.classList.remove('mobile-open');
  backdrop?.classList.remove('show');
  button?.setAttribute('aria-expanded','false');
  button?.setAttribute('aria-label','Open navigation');
  if(button) button.textContent='☰';
  document.body.classList.remove('mobile-nav-open');
}
function toggleMobileNav(){
  const sidebar=$('#sidebar'),backdrop=$('#sidebarBackdrop'),button=$('#mobileMenu');
  if(!sidebar) return;
  const open=!sidebar.classList.contains('mobile-open');
  sidebar.classList.toggle('mobile-open',open);
  backdrop?.classList.toggle('show',open);
  button?.setAttribute('aria-expanded',String(open));
  button?.setAttribute('aria-label',open?'Close navigation':'Open navigation');
  if(button) button.textContent=open?'×':'☰';
  document.body.classList.toggle('mobile-nav-open',open);
}
function openPage(id){
  $$('.page').forEach(p=>p.classList.toggle('active',p.id===id));
  $$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));
  closeMobileNav();
  window.scrollTo({top:0,behavior:'smooth'});
  if(id==='doubts')renderHelp('feed');
  if(id==='roadmaps')renderRoadmaps();
}
function modal(title,text,body='',actions='',editor=false){
  $('#modalTitle').textContent=title;
  $('#modalText').textContent=text;
  $('#modalBody').innerHTML=body;
  $('#modalActions').innerHTML=actions;
  $('#modal').classList.toggle('editor-modal',!!editor);
  $('#modal').classList.add('open');
}
function closeModal(){$('#modal').classList.remove('open');$('#modal').classList.remove('editor-modal')}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function statCards(){return state.platforms.map(p=>`<article><i>${p[1]}</i><label>${p[0]}</label><strong>${p[3]}</strong><small>${p[2]}</small><b>${p[4]}</b></article>`).join('')}
function renderDashboard(){ $('#platformStats').innerHTML=statCards();$('#builderScore').textContent=1840+Math.max(0,state.projects.length-4)*35;$('#profileScore').textContent=$('#builderScore').textContent;$('#dashStreak').textContent=`${state.streak} day streak`;$('#activityFeed').innerHTML=state.activity.map(a=>`<div class="feed-item"><div class="feed-icon">${a[0]==='GitHub'?'GH':a[0]==='LeetCode'?'LC':a[0]==='Team'?'⚡':'◈'}</div><div><b>${esc(a[1])}</b><span>${a[0]}</span></div><time>${a[2]}</time></div>`).join('');$('#activityBars').innerHTML=Array.from({length:18},(_,i)=>`<div class="bar" style="height:${25+(i*17)%70}%"></div>`).join('')}
function renderProfile(){const p=state.profile;$('#profileName').textContent=p.name;$('#profileRole').textContent=p.role;$('#profileBio').textContent=p.bio;$('#profileLocation').textContent=p.location;$('#profileDegree').textContent=p.degree;$('#aboutBox').textContent=`${p.bio} Focused on ${p.specialization}, web development and consistent problem solving.`;$('#profileLinks').innerHTML=state.links.map(l=>`<a href="${l[1]}" target="_blank" rel="noopener">${esc(l[0])} ↗</a>`).join('');$('#miniConnections').innerHTML=state.platforms.map(p=>`<div class="mini-conn"><b>${p[0]}</b><span>${state.connections[p[0]]?'● Connected':'○ Not connected'}</span></div>`).join('');$('#profileProjects').innerHTML=state.projects.slice(0,4).map(x=>`<div class="list-row"><div class="list-icon">◈</div><div><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></div></div>`).join('');$('#profileEducation').innerHTML=state.education.map(x=>`<div class="list-row"><div class="list-icon">🎓</div><div><strong>${esc(x.degree)}</strong><small>${esc(x.school)} · ${esc(x.period)}</small></div></div>`).join('');$('#profileSkills').innerHTML=Object.values(state.skills).flat().slice(0,10).map(x=>`<span class="skill-chip">${esc(x)}</span>`).join('')}
function renderProjects(){const q=($('#projectSearch')?.value||'').toLowerCase();const filter=$('.filter.active')?.dataset.projectFilter||'all';let arr=state.projects.filter(x=>(filter==='all'||(filter==='featured'&&x.featured)||(filter==='verified'&&x.status==='Verified'))&&(!q||`${x.name} ${x.desc} ${x.tech.join(' ')}`.toLowerCase().includes(q)));$('#projectGrid').innerHTML=arr.length?arr.map(x=>`<article class="project-card"><div class="project-top"><div class="project-icon">◈</div><span class="status">${x.status}</span></div><h3>${esc(x.name)}</h3><p>${esc(x.desc)}</p><div class="techs">${x.tech.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-actions"><button class="secondary" data-action="editProject" data-id="${x.id}">Edit</button><button class="primary" data-action="viewProject" data-id="${x.id}">Open project</button></div></article>`).join(''):'<div class="empty">No projects match this filter.</div>'}
function renderEducation(){ $('#educationTimeline').innerHTML=state.education.map(x=>`<article class="card edu-item"><div class="edu-icon">🎓</div><div><h3>${esc(x.degree)}</h3><p>${esc(x.school)}</p><small>${esc(x.period)} · ${esc(x.detail||'')}</small></div><div class="edu-actions"><button class="mini" data-action="editEducation" data-id="${x.id}">Edit</button></div></article>`).join('');$('#achievementGrid').innerHTML=state.achievements.map(a=>`<article class="achievement"><b>${esc(a.icon)}</b><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p></article>`).join('')}
function renderSkills(){ $('#skillGroups').innerHTML=Object.entries(state.skills).map(([g,arr])=>`<article class="skill-group"><div class="card-head"><div><label>SKILL GROUP</label><h3>${esc(g)}</h3></div><button class="mini" data-action="addSkill" data-group="${esc(g)}">＋ Add</button></div><div class="skill-list">${arr.map((s,i)=>`<div class="skill-line"><i>${s.slice(0,2).toUpperCase()}</i><div><strong>${esc(s)}</strong><small>Profile skill</small></div><button data-action="removeSkill" data-group="${esc(g)}" data-index="${i}">×</button></div>`).join('')}</div></article>`).join('')}
function renderTeams(filter='all'){const arr=state.teams.filter(t=>filter==='all'||t.category===filter);$('#teamGrid').innerHTML=arr.map(t=>`<article class="team-card"><div class="team-top"><span class="pill">${esc(t.role)}</span><span class="status">${t.spots} spot${t.spots>1?'s':''}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p><div class="techs">${t.tags.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="team-members">${t.members.map(m=>`<i>${esc(m)}</i>`).join('')}</div><div class="team-meta"><span>${t.members.length} members</span><span>${t.spots} open</span></div><div class="card-actions"><button class="secondary" data-action="teamDetails" data-id="${t.id}">View</button><button class="primary" data-action="joinTeam" data-id="${t.id}">Join request</button></div></article>`).join('')}
let helpTab='feed';
function renderHelp(tab=helpTab){helpTab=tab;const currentUser=(state.profile?.name||'').trim().toLowerCase();const arr=state.help.filter(x=>{const isMine=x.mine===true||String(x.owner||'').trim().toLowerCase()===currentUser;if(tab==='feed')return !isMine&&x.status==='open'&&x.allowFork===true;if(tab==='mine')return isMine;return x.status==='solved'});$('#helpGrid').innerHTML=arr.length?arr.map(x=>`<article class="help-card"><div class="help-top"><div class="help-author"><i>${esc(x.initials)}</i><div><b>${esc(x.owner)}</b><small>${esc(x.tech)} · ${esc(x.age)}</small></div></div><span class="status">${x.status==='solved'?'SOLVED':'OPEN'}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p><pre style="background:#08172d;color:#d7e5f5;border-radius:10px;padding:13px;font:9px/1.6 monospace;min-height:75px;white-space:pre-wrap">${esc(x.code)}</pre><div class="card-actions"><span class="pill">${x.allowFork?'✓ Help Fork Allowed':'Read only'}</span>${x.status==='solved'?'<button class="secondary" disabled>Solution accepted ✓</button>':x.mine?`<button class="secondary" data-action="viewRequest" data-id="${x.id}">Manage request</button>`:`<button class="primary" data-action="forkHelp" data-id="${x.id}" ${x.allowFork?'':'disabled'}>Fork for helping</button>`}</div></article>`).join(''):'<div class="empty">Nothing here yet.</div>'}
function renderCode(){const w=state.workspace;$('#sharedCode').textContent=w?`// Temporary help fork: ${w.title}\n\n${w.code}`:`// Select an allowed Doubt & Help request\n// and click “Fork for helping”.\n\n// Your temporary workspace will appear here.`;$('#workspaceTitle').textContent=w?`Editing: ${w.title}`:'No active help fork';$('#workspaceText').textContent=w?'This is a temporary copy created only for this help request. Edit the code, test your fix, then submit it to the owner.':'Choose “Fork for helping” on an allowed doubt request. Your temporary workspace will open here.';$('#openWorkspace').disabled=!w;$('#workspaceMeta').innerHTML=w?`<div class="meta-line"><span>Owner</span><b>${esc(w.owner)}</b></div><div class="meta-line"><span>Permission</span><b style="color:var(--green)">Explicitly allowed</b></div><div class="meta-line"><span>Request</span><b>#${w.id}</b></div>`:''}
function renderCalendar(){
  const total=Math.max(1,Number(state.challengeLength)||150);
  const done=new Set((state.completed||[]).filter(n=>n<=total));
  $('#challengeTitle').textContent=state.challengeTitle||'Custom Code Challenge';
  $('#challengeTotal').textContent='/ '+total;
  $('#calendar').innerHTML=Array.from({length:total},(_,i)=>{
    const n=i+1;
    const hasCode=!!state.challengeSubmissions?.[n];
    return `<button class="day ${done.has(n)?'done':''} ${n===state.streak+1?'today':''}" data-day="${n}" title="${done.has(n)?'Completed — click to view/edit code':'Submit code to complete Day '+n}">${n}</button>`;
  }).join('');
  $('#streakNumber').textContent=state.streak;
  $('#bestStreak').textContent=state.best;
  $('#completedDays').textContent=state.completed.length;
  $('#calendarPct').textContent=Math.round(state.completed.length/total*100)+'%';
}
function renderPortfolio(){const rows=state.projects.slice(0,4).map(x=>`<div class="row"><span>${esc(x.name)}</span><b>${x.status==='Verified'?'Verified ✓':'Published'}</b></div>`).join('');$('#portfolioRows').innerHTML=rows;$('#portProjects').textContent=state.projects.length;$('#portfolioName').textContent=state.profile.name;$('#approvalQueue').innerHTML=state.approvals.map(a=>`<div class="approval"><i>${esc(a.student.split(' ').map(x=>x[0]).join('').slice(0,2))}</i><span><b>${esc(a.title)}</b><small>${esc(a.student)} · ${esc(a.age)}</small></span><button class="approve" data-action="approve" data-id="${a.id}" ${a.status==='approved'?'disabled':''}>${a.status==='approved'?'Approved ✓':'Approve'}</button></div>`).join('')}
function renderConnections(){const desc={GitHub:'Repositories, contributions and public activity.',LeetCode:'Problem solving, streak and coding progress.',LinkedIn:'Professional profile, education, projects and experience.',HackerRank:'Badges, skills and challenge activity.',CodeChef:'Ratings, contests and coding progress.',Naukri:'Profile readiness and career-facing data.'};$('#connectionGrid').innerHTML=state.platforms.map(p=>`<article class="connection-card"><div class="connection-top"><div class="platform-logo">${p[1]}</div><span class="connection-status">${state.connections[p[0]]?'● CONNECTED':'○ NOT CONNECTED'}</span></div><h3>${p[0]}</h3><p>${desc[p[0]]}</p><button class="${state.connections[p[0]]?'secondary':'primary'} full" data-action="toggleConnection" data-platform="${p[0]}">${state.connections[p[0]]?'Manage / Re-sync':'Connect'}</button></article>`).join('');$('#connectedCount').textContent=Object.values(state.connections).filter(Boolean).length}
