state.roadmapStates=state.roadmapStates||{};
function renderRoadmaps(){
 const chooser=$('#roadmapChooser');if(!chooser)return;
 const selected=state.selectedRoadmap&&ROADMAPS[state.selectedRoadmap];
 chooser.hidden=!!selected;$('#roadmapDetail').hidden=!selected;
 if(!selected){chooser.innerHTML=Object.entries(ROADMAPS).map(([id,r])=>`<button class="roadmap-choice" data-roadmap="${id}"><span class="roadmap-choice-icon">${r.icon}</span><span class="roadmap-choice-copy"><b>${esc(r.title)}</b><small>${esc(r.desc)}</small><em>${r.nodes.length} learning milestones · Interactive path</em></span><span class="roadmap-choice-arrow">→</span></button>`).join('');return}
 $('#roadmapTitle').textContent=selected.title;$('#roadmapDescription').textContent=selected.desc;
 const statuses=state.roadmapStates[state.selectedRoadmap]||(state.roadmapStates[state.selectedRoadmap]={});
 const done=state.roadmapCompleted[state.selectedRoadmap]||[];
 selected.nodes.forEach(n=>{if(!statuses[n.id]&&done.includes(n.id))statuses[n.id]='done'});
 const doneCount=selected.nodes.filter(n=>statuses[n.id]==='done').length;
 const pct=Math.round(doneCount/selected.nodes.length*100);$('#roadmapProgress').textContent=`${pct}% complete · ${doneCount}/${selected.nodes.length}`;
 const nodes=selected.nodes,byId=Object.fromEntries(nodes.map(n=>[n.id,n]));
 const stages=['Beginner','Intermediate','Advanced','Projects','Job-Ready'];
 const width=Math.max(1040,...nodes.map(n=>n.x+260)),height=Math.max(580,...nodes.map(n=>n.y))+100;
 const labels=stages.map((st,i)=>`<g class="roadmap-stage-label" transform="translate(${35+i*300},22)"><rect width="250" height="32" rx="16"/><text x="125" y="21" text-anchor="middle">${st}</text></g>`).join('');
 const paths=selected.edges.map(([a,b])=>{const from=byId[a],to=byId[b];if(!from||!to)return '';const sameColumn=from.x===to.x;const sx=sameColumn?from.x+110:from.x+220,sy=sameColumn?from.y+62:from.y+31,tx=sameColumn?to.x+110:to.x,ty=sameColumn?to.y:to.y+31;const mid=sameColumn?sy+(ty-sy)/2:(sx+tx)/2;const edgeDone=statuses[a]==='done'&&statuses[b]==='done';return `<path class="roadmap-edge ${edgeDone?'edge-done':''}" d="M ${sx} ${sy} C ${sameColumn?sx:mid} ${sameColumn?mid:sy}, ${sameColumn?tx:mid} ${sameColumn?mid:ty}, ${tx} ${ty}"/>`}).join('');
 const boxes=nodes.map(n=>{const status=statuses[n.id]||'not-started',complete=status==='done',skipped=status==='skip',learning=status==='learning';return `<g class="roadmap-node ${complete?'is-complete':''} ${skipped?'is-skipped':''} ${learning?'is-learning':''}" data-roadmap-node="${n.id}" tabindex="0" role="button" aria-label="Open ${esc(n.t)} details" transform="translate(${n.x},${n.y})"><rect width="220" height="62" rx="8"/><text class="node-title" x="110" y="25" text-anchor="middle">${esc(n.t)}</text><text class="node-sub" x="110" y="44" text-anchor="middle">${complete?'✓ Done':skipped?'↷ Skipped':learning?'● Learning':esc(n.stage||'Recommended')}</text><circle class="node-status" cx="220" cy="31" r="11"/><text class="node-check" x="220" y="35" text-anchor="middle">${complete?'✓':skipped?'–':learning?'•':'+'}</text></g>`}).join('');
 $('#roadmapCanvas').innerHTML=`<svg class="roadmap-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(selected.title)} connected roadmap">${labels}${paths}${boxes}</svg>`;
}
function selectRoadmap(id){if(!ROADMAPS[id])return;state.selectedRoadmap=id;save();renderRoadmaps();}
