function forkHelp(id){
  const x=state.help.find(h=>h.id==id);
  if(!x||!x.allowFork)return;
  state.workspace={id:x.id,title:x.title,owner:x.owner,code:x.solution||x.code};
  state.activity.unshift(['Help','Created a temporary help fork for '+x.title,'Just now']);
  save();openPage('code');openWorkspace();
  toast('Temporary help fork opened in the editor.');
}
function openWorkspace(){
  const w=state.workspace;
  if(!w)return;
  modal('Temporary Help Fork','Edit the isolated copy below. Submit your solution when the fix is ready.',`<div class="fork-workspace">
    <div class="workspace-head"><b>${esc(w.title)}</b><span class="pill">Permission: Allowed</span></div>
    <textarea id="forkEditor" spellcheck="false" aria-label="Temporary help fork code editor">${esc(w.code)}</textarea>
    <p class="editor-hint">Tip: Ctrl/Cmd + A selects the code. Your main project is never modified directly.</p>
  </div>`,`<button class="secondary" data-close>Cancel</button><button class="primary" data-action="submitSolution">Submit solution to owner</button>`,true);
  setTimeout(()=>$('#forkEditor')?.focus(),50);
}
function setupChallenge(){
  const total=Math.max(7,Math.min(1000,Number(state.challengeLength)||150));
  modal('Customize your Code Challenge','Choose a goal that fits your schedule. Existing submissions are kept when the goal changes.',`<div class="challenge-setup">
    <div class="field"><label>CHALLENGE NAME</label><input id="challengeName" maxlength="60" value="${esc(state.challengeTitle||'Custom Code Challenge')}"></div>
    <div class="field"><label>GOAL (DAYS)</label><input id="challengeLength" type="number" min="7" max="1000" value="${total}"></div>
    <div class="preview full"><b>How it works:</b> click any day → write/paste code → submit → that day becomes completed. No code submission means no completion.</div>
  </div>`,`<button class="secondary" data-close>Cancel</button><button class="primary" data-action="saveChallenge">Save challenge</button>`);
}
function saveChallenge(){
  const title=$('#challengeName').value.trim()||'Custom Code Challenge';
  const total=Math.max(7,Math.min(1000,Number($('#challengeLength').value)||150));
  state.challengeTitle=title;
  state.challengeLength=total;
  state.completed=(state.completed||[]).filter(n=>n<=total);
  if(state.streak>total)state.streak=total;
  state.best=Math.min(Math.max(state.best,state.streak),total);
  save();closeModal();toast(`${title} set to ${total} days.`);
}
function openDayEditor(day){
  const n=Number(day);
  const total=Math.max(1,Number(state.challengeLength)||150);
  if(!n||n<1||n>total)return;
  const existing=state.challengeSubmissions?.[n]||'';
  const isDone=state.completed.includes(n);
  modal(`Day ${n} · ${state.challengeTitle||'Code Challenge'}`,isDone?'This day is already complete. You can review or update your submitted code.':'Submit code for this day. The day is marked complete only after a non-empty submission.',`<div class="challenge-editor">
    <div class="editor-toolbar"><span class="pill">${isDone?'✓ Completed':'Not completed'}</span><select id="dayLanguage" aria-label="Programming language"><option>JavaScript</option><option>Python</option><option>Java</option><option>C++</option><option>C</option><option>HTML/CSS</option></select></div>
    <textarea id="dayEditor" spellcheck="false" placeholder="// Paste or write your solution here...">${esc(existing)}</textarea>
    <p class="editor-hint">Your code is stored locally in this browser. A blank submission will not complete the day.</p>
  </div>`,`<button class="secondary" data-close>Close</button><button class="primary" data-action="submitDay" data-day="${n}">${isDone?'Update submission':'Submit code & complete Day '+n}</button>`,true);
  setTimeout(()=>$('#dayEditor')?.focus(),50);
}
function submitDay(day){
  const n=Number(day), code=$('#dayEditor')?.value.trim();
  if(!code)return toast('Please write or paste your code before submitting.');
  const total=Math.max(1,Number(state.challengeLength)||150);
  if(n<1||n>total)return;
  state.challengeSubmissions=state.challengeSubmissions||{};
  state.challengeSubmissions[n]={code,language:$('#dayLanguage')?.value||'JavaScript',submittedAt:new Date().toISOString()};
  if(!state.completed.includes(n))state.completed.push(n);
  state.completed.sort((a,b)=>a-b);
  // Streak follows the consecutive sequence from Day 1.
  let streak=0;
  while(state.completed.includes(streak+1))streak++;
  state.streak=streak;
  state.best=Math.max(state.best,streak);
  state.activity.unshift(['LeetCode',`Submitted code for Day ${n} challenge`,'Just now']);
  save();closeModal();toast(`Day ${n} completed successfully.`);
}
